CSS='''<style>:root{--bg:#0A0716;--bg2:#120C22;--txt:#F7F3FF;--suave:#B4ABC8;--sol:#FFC93C;--rosa:#FF4F8B;--nar:#FF8A3D;--borde:rgba(255,255,255,.09);--grad:linear-gradient(115deg,#FFC93C,#FF8A3D 45%,#FF4F8B);color-scheme:dark;box-sizing:border-box;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px)}*{box-sizing:inherit}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--txt);font-family:Manrope,system-ui,sans-serif;line-height:1.55}.wrap{max-width:1100px;margin:0 auto;padding:0 18px}a{color:var(--sol)}
nav{position:sticky;top:env(safe-area-inset-top,0px);z-index:20;background:rgba(10,7,22,.88);backdrop-filter:blur(10px);border-bottom:1px solid var(--borde)}nav .wrap{display:flex;align-items:center;gap:8px;padding:10px 18px}nav b{font-family:Anton,sans-serif;letter-spacing:.04em;white-space:nowrap}.sub-n{display:flex;gap:14px;overflow-x:auto;font-size:.82rem;margin-left:auto;scrollbar-width:none}.sub-n a{color:var(--suave);text-decoration:none;white-space:nowrap}.sub-n a:hover{color:var(--sol)}
.hero{position:relative;padding:54px 0 30px;overflow:hidden}.hero:before{content:"";position:absolute;inset:-40% -10% auto;height:520px;background:radial-gradient(closest-side,rgba(255,79,139,.25),transparent),radial-gradient(closest-side at 70% 40%,rgba(255,201,60,.18),transparent);z-index:-1}
.kick{color:var(--sol);font-size:.75rem;font-weight:800;letter-spacing:.18em;text-transform:uppercase}h1,h2{font-family:Anton,Impact,sans-serif;font-weight:400;text-transform:uppercase;line-height:1.02}h1{font-size:clamp(2.4rem,7vw,4.8rem);margin:10px 0;text-shadow:0 2px 0 #c98a1f,0 4px 0 #7f4a12,0 12px 26px rgba(0,0,0,.6)}h2{font-size:clamp(1.6rem,4vw,2.6rem);margin:0 0 10px;text-shadow:0 2px 0 #3a2457,0 8px 18px rgba(0,0,0,.5)}.grad{font-family:'Playfair Display',serif;font-style:italic;text-transform:none;background:var(--grad);-webkit-background-clip:text;background-clip:text;color:transparent}.lead{color:var(--suave);font-size:1.08rem;max-width:70ch}
.q{font-size:clamp(1.15rem,2.6vw,1.6rem);font-weight:800;max-width:30ch;margin:14px 0 24px}.bigb{display:flex;flex-wrap:wrap;align-items:flex-end;gap:16px;padding:22px;border-radius:24px;background:linear-gradient(135deg,rgba(255,79,139,.16),rgba(255,201,60,.08));border:1px solid rgba(255,79,139,.35)}.bigb b{font-family:Anton,sans-serif;font-size:clamp(3rem,10vw,6rem);line-height:.9;background:var(--grad);-webkit-background-clip:text;background-clip:text;color:transparent;filter:drop-shadow(0 4px 0 #6b2343)}.bigb span{max-width:36ch;font-size:1.05rem}
section{padding:40px 0;border-top:1px solid var(--borde)}.kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px;margin-top:18px}.kpis div{padding:16px;border-radius:18px;background:var(--bg2);border:1px solid var(--borde)}.kpis b{display:block;font-family:Anton,sans-serif;font-size:2rem;background:var(--grad);-webkit-background-clip:text;background-clip:text;color:transparent}.kpis small{color:var(--suave)}
.cons{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:14px}.con{padding:18px;border-radius:20px;background:var(--bg2);border:1px solid var(--borde)}.tag{display:inline-block;font-size:.66rem;font-weight:800;padding:3px 10px;border-radius:99px;background:#9aa0ff;color:#0B0814}.tag.Brecha,.tag.Contradicción{background:var(--rosa)}.tag.Hallazgo{background:#7CF7B0}.tag.Hipótesis,.tag.Vacío{background:var(--sol)}.con h3{margin:10px 0 6px}.con p{margin:0;color:var(--suave)}
.ch{background:var(--bg2);border:1px solid var(--borde);border-radius:20px;padding:16px;margin:14px 0}.ch svg{width:100%;height:auto;display:block}.ch svg text{fill:#ddd;font-family:Manrope,sans-serif}.ch p{color:var(--suave);font-size:.8rem;margin:6px 0 0}
.apps{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:12px}.apps a{display:block;padding:18px;border-radius:18px;background:linear-gradient(135deg,#1b1030,#2a1230);border:1px solid var(--borde);color:var(--txt);text-decoration:none;font-weight:800;transition:transform .2s,border-color .2s}.apps a:hover{transform:translateY(-3px);border-color:rgba(255,201,60,.5)}.apps a span{display:block;color:var(--sol);font-size:.72rem;letter-spacing:.12em;text-transform:uppercase}
.srcs{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:12px}.src{display:block;padding:16px;border-radius:18px;background:var(--bg2);border:1px solid var(--borde);color:var(--txt);text-decoration:none}.src:hover{border-color:rgba(255,201,60,.5)}.src small{display:inline-block;font-size:.64rem;font-weight:800;padding:2px 8px;border-radius:8px;background:rgba(255,255,255,.1)}.src b{display:block;margin:8px 0 4px;color:var(--sol)}.src p{margin:0;color:var(--suave);font-size:.88rem}
.vids{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:14px}.vid{position:relative;padding:0;border:0;border-radius:18px;overflow:hidden;cursor:pointer;aspect-ratio:16/9;background:#000;font:inherit;color:#fff;text-align:left}.vid img{width:100%;height:100%;object-fit:cover;opacity:.7;transition:transform .5s}.vid:hover img{transform:scale(1.05)}.play{position:absolute;left:50%;top:42%;transform:translate(-50%,-50%);width:54px;height:54px;border-radius:50%;display:grid;place-items:center;background:var(--grad);color:#1a0f22}.vt{position:absolute;left:0;right:0;bottom:0;padding:12px;background:linear-gradient(transparent,rgba(0,0,0,.85));font-weight:700;font-size:.88rem}.vt small{display:block;font-weight:400;opacity:.75}.vid iframe{position:absolute;inset:0;width:100%;height:100%;border:0}
.news{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:10px}.nw{display:block;padding:14px;border-radius:14px;background:var(--bg2);border:1px solid var(--borde);color:inherit;text-decoration:none;font-weight:600}.nw small{display:block;font-weight:400;color:var(--suave);margin-bottom:4px}
.ap{padding:22px;border-radius:22px;border:2px dashed rgba(255,255,255,.2)}.ap ol{color:var(--suave)}.wa{display:inline-block;margin-top:8px;padding:12px 18px;border-radius:14px;background:#25D366;color:#06210f;font-weight:800;text-decoration:none}
.cg{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:14px}.cc{position:relative;display:block;padding:22px;border-radius:24px;background:var(--bg2);border:1px solid var(--borde);color:var(--txt);text-decoration:none;overflow:hidden;transition:transform .25s,border-color .25s}.cc:hover{transform:translateY(-4px);border-color:rgba(255,201,60,.5)}.cc .i{font-size:1.8rem}.cc b{display:block;font-family:Anton,sans-serif;font-size:2.4rem;line-height:1;margin:10px 0 2px;background:var(--grad);-webkit-background-clip:text;background-clip:text;color:transparent}.cc small{color:var(--suave);display:block}.cc h3{margin:12px 0 4px}.cc p{margin:0;color:var(--suave);font-size:.92rem}
footer{padding:30px 0 60px;color:var(--suave);font-size:.85rem}</style>'''
def head(t,desc):
    return f'<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover"><title>{E(t)} · Observa Rigor</title><meta name="description" content="{E(desc)}"><meta property="og:title" content="{E(t)} · Observa Rigor"><meta property="og:description" content="{E(desc)}"><meta name="theme-color" content="#0A0716"><link rel="icon" href="data:image/svg+xml,<svg xmlns=\'http://www.w3.org/2000/svg\' viewBox=\'0 0 100 100\'><text y=\'.9em\' font-size=\'90\'>🧭</text></svg>"><link href="https://fonts.googleapis.com/css2?family=Anton&family=Manrope:wght@400;600;800&family=Playfair+Display:ital,wght@1,800&display=swap" rel="stylesheet">'+CSS+'</head><body>'
FOOT='<footer><div class="wrap">Observa Rigor · Lo que no se mide, no se exige. <a href="/clusters/">Todos los clústeres</a></div></footer>'
BAR="""function barras(id,data,o){o=o||{};const W=640,H=220,P=30,n=data.length,bw=(W-2*P)/n,mx=o.max||Math.max(...data.map(d=>d[1]))*1.15,f=v=>new Intl.NumberFormat('es-CO',{maximumFractionDigits:o.dec==null?1:o.dec}).format(v);document.getElementById(id).innerHTML='<svg viewBox="0 0 '+W+' '+(H+30)+'">'+data.map((d,i)=>{const h=d[1]/mx*(H-40),x=P+i*bw+bw*.15,y=H-h;return '<rect x="'+x+'" y="'+y+'" width="'+bw*.7+'" height="'+h+'" rx="6" fill="'+(d[2]||'#9aa0ff')+'"></rect><text x="'+(x+bw*.35)+'" y="'+(y-6)+'" text-anchor="middle" font-size="13" font-weight="700">'+f(d[1])+(o.unit||'')+'</text><text x="'+(x+bw*.35)+'" y="'+(H+16)+'" text-anchor="middle" font-size="11">'+d[0]+'</text>'}).join('')+'</svg>'}"""
def build(OUT,FX='',FICHAS=''):
    os.makedirs(os.path.join(OUT,'clusters'),exist_ok=True)
    idx=head('Clústeres','Las preguntas que investiga Observa Rigor: cifras, conclusiones, cruces de fuentes, investigaciones, videos y noticias.')
    idx+='<nav><div class="wrap"><b><a href="/" style="color:inherit;text-decoration:none">OBSERVA RIGOR</a></b></div></nav><div class="wrap"><div class="hero"><p class="kick">Clústeres de investigación</p><h1>Empezá por una <span class="grad">pregunta</span></h1><p class="lead">Cada clúster es un pequeño observatorio sobre un problema: la cifra que lo resume, lo que sabemos redactado como deber, las gráficas, los cruces de fuentes, las investigaciones serias que lo estudian, videos, noticias en vivo y los aportes de quienes lo viven.</p></div><div class="cg">'
    idx+=''.join(f'<a class="cc" href="/clusters/{c["s"]}/"><span class="i">{c["i"]}</span><b>{E(c["big"])}</b><small>{E(c["bigt"])}</small><h3>{E(c["t"])}</h3><p>{E(c["q"])}</p></a>' for c in C)+'</div></div>'+FOOT+'</body></html>'
    open(os.path.join(OUT,'clusters','index.html'),'w',encoding='utf8').write(idx)
    for c in C:
        secs=[('lo','Lo que sabemos'),('graf','Gráficas') if c['charts'] else None,('cruces','Cruces de fuentes') if c['fichas'] else None,('inv','Investigaciones'),('vid','Videos') if c['vid'] else None,('news','Noticias'),('ap','Aportes')]
        secs=[s for s in secs if s]
        h=head(c['t'],c['q'])+'<nav><div class="wrap"><b><a href="/" style="color:inherit;text-decoration:none">OBSERVA RIGOR</a></b><div class="sub-n">'+''.join(f'<a href="#{a}">{b}</a>' for a,b in secs)+'</div></div></nav><div class="wrap">'
        h+=f'<div class="hero"><p class="kick"><a href="/clusters/">Clústeres</a> · {c["i"]}</p><h1>{E(c["t"])}</h1><p class="q">{E(c["q"])}</p><div class="bigb"><b>{E(c["big"])}</b><span>{E(c["bigt"])}</span></div><div class="kpis">'+''.join(f'<div><b>{E(a)}</b><small>{E(b)}</small></div>' for a,b in c['kpi'])+'</div></div>'
        h+='<section id="lo"><p class="kick">Conclusiones</p><h2>Lo que <span class="grad">sabemos</span></h2><p class="lead">Cada conclusión está redactada como un deber que alguien tiene y no cumple, o como una pregunta cuando todavía no está probada.</p><div class="cons">'+''.join(f'<div class="con"><span class="tag {k}">{k}</span><h3>{E(t)}</h3><p>{E(d)}</p></div>' for k,t,d in c['con'])+'</div></section>'
        if c['charts']:h+='<section id="graf"><p class="kick">Gráficas</p><h2>En <span class="grad">números</span></h2>'+''.join(f'<div class="ch"><b>{E(t)}</b><div id="g-{i}"></div></div>' for i,t,_,_ in c['charts'])+'</section>'
        if c['fichas']:h+='<section id="cruces"><p class="kick">Método Observa Rigor</p><h2>Cruces de <span class="grad">fuentes</span></h2><p class="lead">Fuentes de distinto tipo con la misma llave (lugar, periodo y tema): dónde coinciden, dónde se separan y qué deber está en juego.</p><div id="ley"></div><div id="fichas"></div></section>'
        h+='<section id="apps2"><p class="kick">Míralo en las apps</p><div class="apps">'+''.join(f'<a href="{u}"><span>Ir a</span>{E(t)} →</a>' for u,t in c['apps'])+'</div></section>'
        h+='<section id="inv"><p class="kick">Para profundizar</p><h2>Investigaciones y <span class="grad">fuentes</span></h2><div class="srcs">'+''.join(f'<a class="src" href="{u}" target="_blank" rel="noopener"><small>{TIPO[tp]}</small><b>{E(t)} →</b><p>{E(d)}</p></a>' for tp,t,u,d in c['inv'])+'</div></section>'
        if c['vid']:h+='<section id="vid"><p class="kick">Videos</p><h2>Para <span class="grad">entender</span></h2><div class="vids">'+''.join(f'<button class="vid" data-id="{V[k][0]}"><img src="https://i.ytimg.com/vi/{V[k][0]}/hqdefault.jpg" alt="" loading="lazy"><span class="play">▶</span><span class="vt">{E(V[k][1])}<small>{E(V[k][2])}</small></span></button>' for k in c['vid'])+'</div></section>'
        h+='<section id="news"><p class="kick">En vivo · se actualiza cada hora</p><h2>Lo que está <span class="grad">pasando</span></h2><div id="nl" class="news"><p class="lead">Cargando…</p></div></section>'
        msg=up.quote('Hola, Observa Rigor 👋 Quiero aportar al clúster: '+c['t']+' 📌\n\n1. Qué pasó:\n2. Dónde (barrio o municipio):\n3. Cuándo:\n4. Quién debería responder:')
        h+=f'<section id="ap"><p class="kick">Aportes</p><h2>Contanos lo que <span class="grad">ves</span></h2><div class="ap"><p>Tu aporte entra como <b>señal</b>: se revisa, se cruza con otras fuentes y nunca se publica con nombres de personas ni datos que ubiquen a nadie. Ayudanos contando:</p><ol><li>Qué pasó, sin nombres propios.</li><li>Dónde: barrio o municipio.</li><li>Cuándo, aunque sea aproximado.</li><li>Qué entidad debería estar respondiendo.</li></ol><a class="wa" target="_blank" rel="noopener" href="https://wa.me/573113866341?text={msg}">💬 Aportar por WhatsApp</a></div></section></div>'
        js='<script>'+FX+'\n'+FICHAS+'\n'+BAR+'\n'
        js+=''.join(f"barras('g-{i}',{json.dumps(d,ensure_ascii=False)},{json.dumps(o)});" for i,_,d,o in c['charts'])
        if c['fichas']:js+="FX.css();document.getElementById('ley').innerHTML=FX.leyenda();document.getElementById('fichas').innerHTML="+json.dumps(c['fichas'])+".map(k=>FX.ficha(FICHAS[k])).join('');"
        js+="document.querySelectorAll('.vid').forEach(v=>v.onclick=()=>{if(v.querySelector('iframe'))return;v.insertAdjacentHTML('beforeend','<iframe src=\"https://www.youtube-nocookie.com/embed/'+v.dataset.id+'?autoplay=1&rel=0\" title=\"Video\" allow=\"autoplay; encrypted-media; picture-in-picture\" allowfullscreen></iframe>')});"
        js+="(async()=>{const el=document.getElementById('nl');try{const r=await (await fetch('/api/noticias?t="+c['news']+"')).json();if(!r.ok)throw 0;el.innerHTML=r.items.length?r.items.slice(0,9).map(n=>'<a class=\"nw\" href=\"'+n.u+'\" target=\"_blank\" rel=\"noopener\"><small>'+(n.s||'Prensa')+' · '+new Date(n.f).toLocaleDateString('es-CO',{day:'numeric',month:'short'})+'</small>'+n.t+'</a>').join(''):'<p class=\"lead\">No hay noticias de este tema en los últimos 30 días.</p>'}catch(e){el.innerHTML='<p class=\"lead\">No se pudieron cargar las noticias ahora.</p>'}})();</script>"
        os.makedirs(os.path.join(OUT,'clusters',c['s']),exist_ok=True)
        open(os.path.join(OUT,'clusters',c['s'],'index.html'),'w',encoding='utf8').write(h+FOOT+js+'</body></html>')
    print('  ✓ clusters/ (%d clústeres)'%len(C))
